function HotspotLayer({ hotspots, bounds, visible }) {
  if (!bounds) return null;

  const toPx = (ix, iy) => ({
    x: bounds.left + (ix / 100) * bounds.width,
    y: bounds.top  + (iy / 100) * bounds.height,
  });

  // Larger, asymmetric gaps to push labels clear of the map
  const labelAnchor = (dot, anchor) => {
    if (anchor === "right")  return { x: dot.x + 72, y: dot.y };
    if (anchor === "bottom") return { x: dot.x,      y: dot.y + 48 };
    return                          { x: dot.x - 72, y: dot.y };   // "left"
  };

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        pointerEvents: "none",
        opacity: visible ? 1 : 0,
        transition: "opacity 0.32s ease",
      }}
    >
      <svg
        style={{ position: "absolute", inset: 0, width: "100%", height: "100%", overflow: "visible" }}
      >
        <defs>
          {/* Outer glow ring */}
          <radialGradient id="glowOuter" cx="50%" cy="50%" r="50%">
            <stop offset="0%"   stopColor="#ff6600" stopOpacity="0.55" />
            <stop offset="100%" stopColor="#880000" stopOpacity="0"    />
          </radialGradient>
          {/* Inner hot core */}
          <radialGradient id="glowCore" cx="50%" cy="50%" r="50%">
            <stop offset="0%"   stopColor="#ffffff" stopOpacity="1"    />
            <stop offset="40%"  stopColor="#ff8800" stopOpacity="0.95" />
            <stop offset="100%" stopColor="#cc2200" stopOpacity="0"    />
          </radialGradient>
        </defs>

        {hotspots.map((h, i) => {
          const dot = toPx(h.ix, h.iy);
          const lbl = labelAnchor(dot, h.anchor);

          // Line from dot surface → label
          const dx   = lbl.x - dot.x;
          const dy   = lbl.y - dot.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          const ux   = dx / dist;
          const uy   = dy / dist;

          return (
            <g key={i}>
              {/* Connector line */}
              <line
                x1={dot.x + ux * 8} y1={dot.y + uy * 8}
                x2={lbl.x}          y2={lbl.y}
                stroke="#cc0000"
                strokeWidth="1"
                strokeLinecap="round"
              />

              {/* Outer diffuse glow (large halo) */}
              <circle cx={dot.x} cy={dot.y} r="20" fill="url(#glowOuter)" />
              {/* Inner hot glow */}
              <circle cx={dot.x} cy={dot.y} r="10" fill="url(#glowCore)"  />
              {/* Solid orange ring */}
              <circle cx={dot.x} cy={dot.y} r="5"  fill="#ff4400" opacity="0.9" />
              {/* Bright white core */}
              <circle cx={dot.x} cy={dot.y} r="2"  fill="white" />
            </g>
          );
        })}
      </svg>

      {/* Labels */}
      {hotspots.map((h, i) => {
        const dot = toPx(h.ix, h.iy);
        const lbl = labelAnchor(dot, h.anchor);

        const textAlign =
          h.anchor === "right"  ? "left"   :
          h.anchor === "bottom" ? "center" : "right";

        const transform =
          h.anchor === "right"  ? "translate(0, -50%)"    :
          h.anchor === "bottom" ? "translate(-50%, 0)"    :
                                  "translate(-100%, -50%)";

        return (
          <div
            key={i}
            style={{
              position:   "absolute",
              left:       lbl.x,
              top:        lbl.y,
              transform,
              textAlign,
              fontFamily: "'Inter','Helvetica Neue',sans-serif",
              whiteSpace: "nowrap",
              color:      "white",
            }}
          >
            <div style={{ fontSize: "clamp(12px, 1.4vw, 19px)", fontWeight: 700, lineHeight: 1.1 }}>
              {h.pct}
            </div>
            <div style={{ fontSize: "clamp(8px, 0.8vw, 11px)", opacity: 0.75, marginTop: 2, fontWeight: 400 }}>
              {h.label}
            </div>
          </div>
        );
      })}
    </div>
  );
}
